query:
-- Update freeze-dried candy prices
UPDATE products SET basePrice = 4.00 WHERE name LIKE '%Freeze%' AND name LIKE '%Mini%';
UPDATE products SET basePrice = 6.00 WHERE name LIKE '%Freeze%' AND name LIKE '%Small%';
UPDATE products SET basePrice = 10.00 WHERE name LIKE '%Freeze%' AND name LIKE '%Large%';

-- Also update in Bickering Bros category if they exist
UPDATE products SET basePrice = 5.00 WHERE categoryId = (SELECT id FROM categories WHERE slug = 'bickering-bros' LIMIT 1) AND basePrice != 5.00;

